<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_admin();
$selected=(int)($_GET['customer_id']??$_POST['customer_id']??0); $errors=[]; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$text=trim((string)($_POST['message']??''));$selected=(int)($_POST['customer_id']??0);$action=$_POST['action']??'send';
 if($action==='send'){if(!$selected||$text==='')$errors[]='Select a customer and enter a message.';else{$pdo->prepare("INSERT INTO customer_private_messages(customer_id,sender_type,sender_id,message,is_read) VALUES(?, 'ADMIN', ?, ?, 0)")->execute([$selected,(int)$_SESSION['admin_id'],$text]);$msg='Private message sent.';}}
}
try{$customers=$pdo->query("SELECT c.customer_id,c.full_name,c.email,c.phone,c.status,c.last_seen_at,(SELECT COUNT(*) FROM customer_private_messages pm WHERE pm.customer_id=c.customer_id AND pm.sender_type='CUSTOMER' AND pm.is_read=0) unread FROM customers c ORDER BY unread DESC,c.full_name")->fetchAll();}catch(Throwable $e){$customers=[];}
$chat=[]; if($selected){$s=$pdo->prepare('SELECT * FROM customer_private_messages WHERE customer_id=? ORDER BY created_at ASC,message_id ASC');$s->execute([$selected]);$chat=$s->fetchAll();$pdo->prepare("UPDATE customer_private_messages SET is_read=1 WHERE customer_id=? AND sender_type='CUSTOMER'")->execute([$selected]);}
$title='Private Customer Chat'; require __DIR__.'/../includes/header.php';
?><div class="section-head"><div><span class="eyebrow">PRIVATE CUSTOMER SUPPORT</span><h1>Customer conversations</h1><p>Each conversation is isolated to one customer and management.</p></div></div><?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?><?php foreach($errors as $x): ?><div class="errors"><?=e($x)?></div><?php endforeach; ?><div class="private-chat-layout"><aside class="panel customer-chat-list"><h2>Customers</h2><?php foreach($customers as $c): ?><a class="customer-chat-link <?=$selected===(int)$c['customer_id']?'active':''?>" href="/admin/messages.php?customer_id=<?=$c['customer_id']?>"><span><strong><?=e($c['full_name'])?></strong><small><?=e($c['email'])?></small></span><?php if((int)$c['unread']): ?><b class="badge"><?=$c['unread']?></b><?php endif; ?><em><?=($c['last_seen_at'] && strtotime($c['last_seen_at'])>=time()-300)?'Online':'Offline'?></em></a><?php endforeach; ?></aside><section class="chat-shell panel"><?php if($selected): ?><div class="chat-head"><strong><?php foreach($customers as $c) if((int)$c['customer_id']===$selected) echo e($c['full_name']); ?></strong><span>Private support chat</span></div><div class="chat-messages"><?php foreach($chat as $r): ?><div class="chat-row <?=strtolower($r['sender_type'])==='admin'?'mine':'theirs'?>"><div class="chat-bubble"><small><?=strtolower($r['sender_type'])==='admin'?'Management':'Customer'?> · <?=e($r['created_at'])?></small><p><?=nl2br(e($r['message']))?></p></div></div><?php endforeach; ?><?php if(!$chat): ?><div class="empty"><h3>No messages yet</h3><p>Start the private conversation below.</p></div><?php endif; ?></div><form method="post" class="chat-compose"><?=csrf_field()?><input type="hidden" name="customer_id" value="<?=$selected?>"><input type="hidden" name="action" value="send"><textarea name="message" maxlength="4000" required placeholder="Reply privately..."></textarea><button class="btn primary">Send private reply</button></form><?php else: ?><div class="empty"><h2>Select a customer</h2><p>Choose a registered member to open their private conversation.</p></div><?php endif; ?></section></div><?php require __DIR__.'/../includes/footer.php'; ?>